ruleExplore.coverUrl:
a@href
@js:
var match = result.match(/(\d+)(?=[^\d]*$)/);
var id = match ? match[1] : '';
var iid = parseInt(id / 1000);
'/files/article/image/' + iid + '/' + id + '/' + id + 's.jpg';

